<script setup lang="ts">
// SPDX-License-Identifier: AGPL-3.0-only
import {ref,computed,onBeforeUnmount} from 'vue'
import {useWorkspace} from '../state/workspace'
import {actions,reviewDigest,validateManualActions} from '../domain/review'
const store=useWorkspace(),selected=ref<string[]>([]),busy=ref(false),error=ref(''),result=ref<any>(null)
const candidates=computed(()=>store.reviews.value.map(review=>{const job=store.jobFor(review),draft=job?store.filingDrafts.value[job.id]:null;let manual;try{manual=draft?validateManualActions({target:draft.target,addTags:draft.tags.split(',').map(t=>t.trim()).filter(Boolean)}):undefined}catch{return null}if(!review.proposal||!job||job.decision||store.fieldDrafts.value[JSON.stringify([review.bundle.source.resourceId,review.bundle.source.sha256])])return null;try{return{job,review,manual,plan:actions(review,store.policy.value,manual)}}catch{return null}}).filter(row=>row!==null&&row.plan))
let timer:ReturnType<typeof setTimeout>|undefined,alive=true
onBeforeUnmount(()=>{alive=false;clearTimeout(timer)})
async function poll(id:string){try{const value=await store.request('operation',{id});if(!alive)return;result.value=value;if(['queued','running'].includes(value.state))timer=setTimeout(()=>void poll(id),1500);else{busy.value=false;await store.connect()}}catch(e){if(alive){busy.value=false;error.value=e instanceof Error?e.message:'Inspect operation history'}}}
async function file(){busy.value=true;error.value='';try{const policy=JSON.parse(JSON.stringify(store.policy.value)),items=[];for(const row of candidates.value.filter(r=>selected.value.includes(r.job.id)))items.push({id:row.job.id,policy,reviewDigest:await reviewDigest(row.review,policy,row.manual),...(row.manual?{manualActions:row.manual}:{})});if(!items.length)throw new Error('Choose at least one current review');const value=await store.request('operation-start',{id:crypto.randomUUID(),kind:'file',items});result.value=value;selected.value=[];void poll(value.id)}catch(e){busy.value=false;error.value=e instanceof Error?e.message:'Batch filing held'}}
</script>
<template><details v-if="candidates.length>1 || result" class="panel batch-review"><summary>Review &amp; file several documents</summary><p>Inspect each destination and tags below, then select the plans you want to apply. Documents with unsaved field drafts need an individual review.</p><button class="button subtle" :disabled="busy" @click="selected=candidates.map(row=>row.job.id)">Select all shown plans</button><button class="button subtle" :disabled="busy" @click="selected=[]">Clear selection</button><div v-for="row in candidates" :key="row.job.id" class="batch-plan"><label><input v-model="selected" type="checkbox" :value="row.job.id" :disabled="busy" /> {{ row.review.bundle.source.path.split('/').pop() }}</label><p>{{ row.review.proposal!.issuer.value }} · {{ row.review.proposal!.date.value }}</p><p>{{ row.plan!.target }}</p><small>Tags: {{ row.plan!.addTags.join(', ') || 'None' }}</small><button class="button subtle" :disabled="busy" @click="store.selected.value=store.reviews.value.indexOf(row.review)">Inspect PDF</button></div><button class="button primary" :disabled="busy || !selected.length" @click="file">Approve and file {{ selected.length }} selected documents</button><p v-if="error" role="alert" class="error">{{ error }}</p><ul v-if="result"><li v-for="item in result.items" :key="item.position">{{ item.input.id.slice(0,12) }} · {{ item.state }} {{ item.result?.error || '' }}</li></ul></details></template>
<style scoped>summary{cursor:pointer;color:var(--accent-text);font-weight:600}.batch-plan{border-top:1px solid var(--line);padding:14px 0}.batch-plan label{display:flex;gap:10px}.batch-plan p{margin:5px 0;font-size:12px;overflow-wrap:anywhere}.batch-plan small{display:block;font-size:11px;color:var(--muted)}li{font-size:12px;overflow-wrap:anywhere}</style>
